builder.Services.AddOpenTelemetry()
    .UseAzureMonitor(options =>
    {
        options.ConnectionString = builder.Configuration["ApplicationInsights:ConnectionString"];
    })
    .ConfigureResource(r => r
        .AddService("orders-api")
        .AddAttributes(new Dictionary<string, object>
        {
            ["deployment.environment"] = builder.Environment.EnvironmentName
        }));

// appsettings.json:
// "ApplicationInsights": { "ConnectionString": "InstrumentationKey=...;IngestionEndpoint=..." }

public class CheckoutService(TelemetryClient telemetry)
{
    public async Task CompleteAsync(Order order)
    {
        var sw = Stopwatch.StartNew();
        try
        {
            await _payment.ChargeAsync(order.Total);
            telemetry.TrackEvent("CheckoutCompleted",
                properties: new Dictionary<string, string>
                {
                    ["OrderId"] = order.Id.ToString(),
                    ["PaymentMethod"] = order.PaymentMethod
                },
                metrics: new Dictionary<string, double> { ["OrderTotal"] = (double)order.Total });
        }
        catch (Exception ex)
        {
            telemetry.TrackException(ex, new Dictionary<string, string>
            {
                ["OrderId"] = order.Id.ToString()
            });
            throw;
        }
        finally
        {
            telemetry.TrackMetric("Checkout.DurationMs", sw.ElapsedMilliseconds);
        }
    }
}
